  aimsGuidance: "AIMS — complete form awaiting source. The tardive-dyskinesia criteria reference AIMS but do not contain its complete form, so no items are shown and none are invented. Present tardive dyskinesia cannot clear questionnaire completion until the complete source is reviewed. Research thresholds only (Schooler-Kane): a regional score of 3 or greater in one region, or 2 or greater in at least two regions, with at least 3 months cumulative exposure and no alternative cause — never a total score, never a diagnosis.",
  barsGuidance: "Full BARS: observe seated then standing (2 minutes each, neutral conversation), note other movements, then ask about inner restlessness directly. All 4 items are required when present.",
  sasGuidance: "Full SAS: ten-item examination for dopamine-blocking-drug-induced parkinsonian signs (rigidity emphasis). Use the same conditions and, when possible, the same trained rater for serial assessments. All 10 items are required when present. Original convention: mean up to 0.3 within normal; greater than 0.3 abnormal. No mild/moderate/severe bands exist — reviewed severity is independent.",
  dystoniaGuidance: "Acute Dystonia Dx Criteria: criteria-based checklist drafted from the supplied criteria. There is no numeric scale and no total score. All 5 criteria are required when present. Screen for stridor or breathing difficulty at once — airway evaluation never waits for this checklist.",
  effectsIntro: "Each of the four follow-up effects is present, absent, or not assessed. Nothing is pre-filled. Answers autosave through the same draft as the rest of this encounter (about one second after changing an answer). Full questionnaire completion is required only when the corresponding effect is present; absent and not-assessed effects carry null severity with no completion requirement. Every result below is computed by the server.",
  airwayWarning: "Stridor or breathing difficulty was recorded (addx_urgent_airway yes), suggesting possible laryngeal dystonia. Do not delay airway evaluation to complete the checklist or wait for any other result. This warning persists until the answer changes.",
  historyIntro: "Review medication exposure, prior treatment and movement history. Select Unknown when you cannot determine an answer. Other proposal context may also offer Not assessed when it has not been reviewed. Responses save automatically.",
  historyCountHint: "Follow-up fields can appear or disappear as answers change, so the response count and total can change.",
