  aimsCompleteFormAwaitingSourceTheTardive: "AIMS — فرم کامل در انتظار منبع است. معیارهای دیسکینزی دیررس به AIMS اشاره دارند، اما فرم کامل آن را ندارند؛ بنابراین هیچ موردی نمایش داده یا ابداع نمی‌شود. در صورت وجود دیسکینزی دیررس، تا بازبینی منبع کامل، پرسش‌نامه نمی‌تواند کامل تلقی شود. صرفاً آستانه‌های پژوهشی (Schooler-Kane): نمرهٔ ناحیه‌ای ۳ یا بیشتر در یک ناحیه، یا ۲ یا بیشتر در دست‌کم دو ناحیه، با دست‌کم ۳ ماه مواجههٔ تجمعی و بدون علت جایگزین — نه نمرهٔ کل و نه تشخیص.",
  fullBarsObserveSeatedThenStanding2: "BARS کامل: در حالت نشسته و سپس ایستاده مشاهده کنید (هر کدام ۲ دقیقه، با گفت‌وگوی خنثی)، حرکات دیگر را ثبت کنید و سپس مستقیماً دربارهٔ بی‌قراری درونی بپرسید. در صورت وجود عارضه، هر ۴ مورد الزامی است.",
  fullSasTenItemExaminationForDopamine: "SAS کامل: معاینهٔ ده‌موردی علائم پارکینسونی ناشی از داروهای مسدودکنندهٔ دوپامین (با تأکید بر سفتی). برای ارزیابی‌های متوالی از شرایط یکسان و در صورت امکان همان ارزیاب آموزش‌دیده استفاده کنید. در صورت وجود عارضه، هر ۱۰ مورد الزامی است. طبق قرارداد اولیه، میانگین تا ۰٫۳ طبیعی و بیشتر از ۰٫۳ غیرطبیعی است. بازه‌های خفیف، متوسط و شدید تعریف نشده‌اند — شدت بازبینی‌شده مستقل است.",
