  ddiSpan: " · بازهٔ {start}–{end}",
  aimsGuidance: "AIMS — فرم کامل در انتظار منبع است. معیارهای دیسکینزی دیررس به AIMS ارجاع می‌دهند، اما فرم کامل آن را ندارند؛ بنابراین هیچ موردی نمایش داده یا ابداع نمی‌شود. در صورت وجود دیسکینزی دیررس، تا بررسی منبع کامل نمی‌توان تکمیل پرسش‌نامه را تأیید کرد. آستانه‌های صرفاً پژوهشی (Schooler-Kane): نمرهٔ منطقه‌ای ۳ یا بیشتر در یک منطقه، یا ۲ یا بیشتر در دست‌کم دو منطقه، همراه با حداقل ۳ ماه مواجههٔ تجمعی و نبود علت جایگزین — نه نمرهٔ کل و نه تشخیص.",
  barsGuidance: "BARS کامل: ابتدا در حالت نشسته و سپس ایستاده مشاهده کنید (هرکدام ۲ دقیقه، با گفت‌وگوی خنثی)، سایر حرکات را یادداشت کنید و سپس مستقیماً دربارهٔ بی‌قراری درونی بپرسید. در صورت وجود عارضه هر ۴ مورد الزامی است.",
  sasGuidance: "SAS کامل: معاینهٔ ده‌موردی برای نشانه‌های پارکینسونی ناشی از داروهای مسدودکنندهٔ دوپامین (با تأکید بر سفتی). در ارزیابی‌های متوالی از شرایط یکسان و در صورت امکان از همان ارزیاب آموزش‌دیده استفاده کنید. در صورت وجود عارضه هر ۱۰ مورد الزامی است. قرارداد اصلی: میانگین تا ۰٫۳ طبیعی و بیشتر از ۰٫۳ غیرطبیعی است. طبقه‌بندی خفیف، متوسط یا شدید وجود ندارد — شدتِ بررسی‌شده مستقل است.",
  dystoniaGuidance: "معیارهای تشخیصی دیستونی حاد: چک‌لیستی مبتنی بر معیارهای ارائه‌شده. مقیاس عددی یا نمرهٔ کل وجود ندارد. در صورت وجود عارضه هر ۵ معیار الزامی است. فوراً استریدور یا دشواری تنفس را بررسی کنید — ارزیابی راه هوایی هرگز منتظر این چک‌لیست نمی‌ماند.",
  effectsIntro: "هر یک از چهار عارضهٔ پیگیری می‌تواند موجود، ناموجود یا ارزیابی‌نشده باشد. هیچ پاسخی از پیش وارد نشده است. پاسخ‌ها در همان پیش‌نویس ویزیت به‌طور خودکار ذخیره می‌شوند (حدود یک ثانیه پس از تغییر پاسخ). تکمیل کامل پرسش‌نامه فقط در صورت وجود عارضهٔ مربوط الزامی است؛ برای عوارض ناموجود و ارزیابی‌نشده شدت تهی است و تکمیل الزامی نیست. تمام نتایج زیر توسط سرور محاسبه می‌شوند.",
  airwayWarning: "استریدور یا دشواری تنفس ثبت شده است (addx_urgent_airway yes) و احتمال دیستونی حنجره را مطرح می‌کند. ارزیابی راه هوایی را برای تکمیل چک‌لیست یا انتظار برای نتیجهٔ دیگر به تأخیر نیندازید. این هشدار تا تغییر پاسخ باقی می‌ماند.",
  historyIntro: "سابقهٔ مواجهه با دارو، درمان قبلی و حرکات را بررسی کنید. وقتی نمی‌توانید پاسخی تعیین کنید «نامشخص» را انتخاب کنید. سایر اطلاعات زمینه‌ای پیشنهاد ممکن است در صورت بررسی‌نشدن گزینهٔ «ارزیابی‌نشده» نیز داشته باشند. پاسخ‌ها به‌طور خودکار ذخیره می‌شوند.",
  historyCountHint: "با تغییر پاسخ‌ها ممکن است فیلدهای پیگیری ظاهر یا پنهان شوند؛ بنابراین تعداد پاسخ‌ها و تعداد کل ممکن است تغییر کند.",
  historyContextHint: "این اطلاعات زمینه‌ای را برای تولید پیشنهاد بررسی کنید. اطلاعات نامطمئن با بیان عدم قطعیت برآورد می‌شوند و مانع تولید نیستند؛ فقط ورودی‌های پیش‌نیاز متناقض، ارزیابی‌نشده، نامعتبر یا مفقود، سؤال مربوط را متوقف می‌کنند.",
  historySummaryHint: "«نامشخص» و «ارزیابی‌نشده» جدا از «خیر» ثبت می‌شوند. تعداد پاسخ‌ها نشان‌دهندهٔ یافته‌های بالینی نیست.",
  ddiRepeatedEvidence: "موارد تکراری خروجی، محل منبع خود را حفظ می‌کنند؛ این موارد تأیید بالینی مستقل نیستند.",
